create temp table ic_results(name text,ok boolean);
create function pg_temp.ic_test(n text,b boolean) returns void language plpgsql as $$begin insert into ic_results values(n,coalesce(b,false));end$$;
insert into auth.users(id,email) values('07111900-0000-4000-8000-000000000001','ic-rollback-only@example.invalid');
insert into members(id,name,auth_id) values('CC-IC-M','rollback fixture','07111900-0000-4000-8000-000000000001');
insert into ticket_types(id,name,category) values('CC-IC-TT','rollback fixture','私人教練');
insert into member_tickets(id,member_id,ticket_type_id,plan_name,sessions_total,sessions_remaining,unlocked_sessions,amount_paid,status,installment)
values('CC-IC-T','CC-IC-M','CC-IC-TT','rollback fixture',12,12,4,4000,'usable','{"count":3,"current":1,"segments":[4,4,4],"amounts":[4000,4000,4000],"paid":[true,false,false]}');
insert into contracts(id,member_id,ticket_id,sign_type,signed_at) values('CC-IC-C','CC-IC-M','CC-IC-T','remote',now());
do $$
declare term jsonb; term2 jsonb; r jsonb; rid text; rid2 text; before_amt numeric; before_u int; blocked boolean;
begin
 perform set_config('request.jwt.claim.sub','7d01aa40-db57-4e26-a49a-b3a5d1dc5722',true);
 term:=fn_installment_terms('CC-IC-T',4,4000,'cash',0);
 perform pg_temp.ic_test('period bounds',term->>'period_from'='2' and term->>'period_to'='2');
 r:=fn_installment_collect_v2('CC-IC-T','receipt_unsigned',term,false,'{"mode":"none"}');
 perform pg_temp.ic_test('unsigned rejected',r->>'error_code'='INSTALLMENT.SIGNATURE_REQUIRED');
 perform pg_temp.ic_test('unsigned no write',not exists(select 1 from installment_receipts));
 r:=fn_installment_request_v2('CC-IC-T',term);rid:=r->>'request_id';
 perform pg_temp.ic_test('request generated',r->>'ok'='true' and rid is not null);
 r:=fn_member_sign_installment_v2('CC-IC-C',rid,'data:image/png;base64,'||repeat('A',240));
 perform pg_temp.ic_test('wrong member rejected',r->>'error_code'='AUTH.FORBIDDEN');
 perform set_config('request.jwt.claim.sub','07111900-0000-4000-8000-000000000001',true);
 r:=fn_member_sign_installment('CC-IC-C',2,'data:image/png;base64,'||repeat('A',240));
 perform pg_temp.ic_test('old page must refresh',r->>'error_code'='INSTALLMENT.REFRESH_REQUIRED');
 r:=fn_member_sign_installment_v2('CC-IC-C',rid,'data:image/png;base64,'||repeat('A',240));
 perform pg_temp.ic_test('member signs exact request',r->>'ok'='true');
 perform pg_temp.ic_test('signature does not unlock',(select unlocked_sessions=4 from member_tickets where id='CC-IC-T'));
 perform set_config('request.jwt.claim.sub','7d01aa40-db57-4e26-a49a-b3a5d1dc5722',true);
 term2:=fn_installment_terms('CC-IC-T',4,3900,'cash',0);
 r:=fn_installment_collect_v2('CC-IC-T','receipt_changed',term2,false,'{"mode":"none"}');
 perform pg_temp.ic_test('changed fee must resign',r->>'error_code'='INSTALLMENT.SIGNATURE_REQUIRED');
 r:=fn_installment_request_v2('CC-IC-T',term2);rid2:=r->>'request_id';
 perform pg_temp.ic_test('new signature preserves previous',(select jsonb_array_length(installment_signs)=2 and installment_signs->0->>'signature' is not null from contracts where id='CC-IC-C'));
 perform set_config('request.jwt.claim.sub','07111900-0000-4000-8000-000000000001',true);
 r:=fn_member_sign_installment_v2('CC-IC-C',rid,'data:image/png;base64,'||repeat('A',240));
 perform pg_temp.ic_test('stale signature page rejected',r->>'error_code'='INSTALLMENT.PLAN_CHANGED');
 r:=fn_member_sign_installment_v2('CC-IC-C',rid2,'data:image/png;base64,'||repeat('B',240));
 perform pg_temp.ic_test('changed terms signable',r->>'ok'='true');
 perform set_config('request.jwt.claim.sub','7d01aa40-db57-4e26-a49a-b3a5d1dc5722',true);
 r:=fn_installment_collect_v2('CC-IC-T','receipt_good',term2,false,'{"mode":"none"}');
 perform pg_temp.ic_test('collection success '||r::text,r->>'ok'='true');
 perform pg_temp.ic_test('balance and unlock consistent',(select unlocked_sessions=8 and amount_paid=7900 and sessions_remaining=12 from member_tickets where id='CC-IC-T'));
 perform pg_temp.ic_test('one purchase one zero adjust',(select count(*)=1 from purchases where ticket_id='CC-IC-T') and (select count(*)=1 and sum(delta)=0 from ticket_logs where ticket_id='CC-IC-T'));
 r:=fn_installment_collect_v2('CC-IC-T','receipt_good',term2,false,'{"mode":"none"}');
 perform pg_temp.ic_test('same receipt idempotent',r->>'ok'='true' and r->>'already'='true');
 perform pg_temp.ic_test('receipt links exact signature request',(select signature_request_id=rid2 from installment_receipts where id='receipt_good'));
 r:=fn_installment_collect_v2('CC-IC-T','receipt_good',term2,false,'{"mode":"carrier","email":"other@example.invalid"}');
 perform pg_temp.ic_test('receipt content immutable',r->>'error_code'='INSTALLMENT.RECEIPT_CONFLICT');
 r:=fn_installment_collect_v2('CC-IC-T','receipt_another',term2,false,'{"mode":"none"}');
 perform pg_temp.ic_test('second request stale terms rejected',r->>'error_code'='INSTALLMENT.PLAN_CHANGED');
 blocked:=false;begin update member_tickets set unlocked_sessions=12 where id='CC-IC-T';exception when others then blocked:=sqlerrm='INSTALLMENT.COLLECTION_REQUIRED';end;
 perform pg_temp.ic_test('old direct write blocked',blocked);
 update contracts set sign_type='paper' where id='CC-IC-C';
 term:=fn_installment_terms('CC-IC-T',4,4000,'transfer',0);
 r:=fn_installment_collect_v2('CC-IC-T','receipt_paper',term,false,'{"mode":"none"}');
 perform pg_temp.ic_test('paper needs acknowledgement',r->>'error_code'='INSTALLMENT.PAPER_REQUIRED');
 r:=fn_installment_collect_v2('CC-IC-T','receipt_paper',term,true,null);
 perform pg_temp.ic_test('invoice choice required',r->>'error_code'='INVOICE.CHOICE_REQUIRED');
 r:=fn_installment_collect_v2('CC-IC-T','receipt_paper',term,true,'{"mode":"none"}');
 perform pg_temp.ic_test('paper collects correctly '||r::text,r->>'ok'='true');
 perform pg_temp.ic_test('paper ack retained honestly',(select paper_ack and invoice_choice->>'mode'='none' from installment_receipts where id='receipt_paper'));
 perform pg_temp.ic_test('all remaining open',(select unlocked_sessions=12 and amount_paid=11900 and sessions_remaining=12 from member_tickets where id='CC-IC-T'));
 perform set_config('request.jwt.claim.sub','07111900-0000-4000-8000-000000000001',true);
 r:=fn_installment_request_v2('CC-IC-T',term);
 perform pg_temp.ic_test('member cannot request',r->>'error_code'='AUTH.NOT_DESK');
 r:=fn_installment_collect_v2('CC-IC-T','receipt_forbidden',term,true,'{"mode":"none"}');
 perform pg_temp.ic_test('member cannot collect',r->>'error_code'='AUTH.NOT_DESK');
 perform pg_temp.ic_test('anonymous RPC denied',not has_function_privilege('anon','fn_installment_collect_v2(text,text,jsonb,boolean,jsonb)','execute'));
 perform pg_temp.ic_test('receipt direct insert denied',not has_table_privilege('authenticated','installment_receipts','insert'));
end$$;
select jsonb_build_object('passed',count(*) filter(where ok),'failed',count(*) filter(where not ok),'failures',coalesce(jsonb_agg(name) filter(where not ok),'[]')) as result from ic_results;
-- Failure injection is transaction-local; no real bookings are touched.
insert into ticket_types(id,name,category) values('tt-discount-pt300','test voucher','私人教練') on conflict(id) do nothing;
insert into member_tickets(id,member_id,ticket_type_id,plan_name,sessions_total,sessions_remaining,unlocked_sessions,amount_paid,status,installment)
values('CC-IC-VT','CC-IC-M','CC-IC-TT','rollback voucher target',12,12,4,4000,'usable','{"count":3,"current":1,"segments":[4,4,4],"amounts":[4000,4000,4000],"paid":[true,false,false]}'),
('CC-IC-V','CC-IC-M','tt-discount-pt300','voucher',2,2,null,0,'usable',null);
insert into contracts(id,member_id,ticket_id,sign_type,signed_at) values('CC-IC-VC','CC-IC-M','CC-IC-VT','paper',now());
create function pg_temp.ic_purchase_fail() returns trigger language plpgsql as $$ begin if new.id='PUR-INST-receipt_fail' then raise exception 'TEST.PURCHASE_FAIL';end if;return new;end$$;
create trigger zz_ic_purchase_fail before insert on purchases for each row execute function pg_temp.ic_purchase_fail();
do $$declare term jsonb; r jsonb; blocked boolean; c contracts%rowtype; e jsonb;
begin
 perform set_config('request.jwt.claim.sub','7d01aa40-db57-4e26-a49a-b3a5d1dc5722',true);
 term:=fn_installment_terms('CC-IC-VT',4,3700,'cash',1);
 r:=fn_installment_collect_v2('CC-IC-VT','receipt_fail',term,true,'{"mode":"none"}');
 perform pg_temp.ic_test('injected purchase failure detected',r->>'error_code'='TEST.PURCHASE_FAIL');
 perform pg_temp.ic_test('failed transaction restores ticket',(select unlocked_sessions=4 and amount_paid=4000 from member_tickets where id='CC-IC-VT'));
 perform pg_temp.ic_test('failed transaction restores voucher',(select sessions_remaining=2 from member_tickets where id='CC-IC-V'));
 perform pg_temp.ic_test('failed transaction leaves no receipt or ledger',not exists(select 1 from installment_receipts where id='receipt_fail') and not exists(select 1 from ticket_logs where ticket_id in ('CC-IC-VT','CC-IC-V')));
 r:=fn_installment_collect_v2('CC-IC-VT','receipt_voucher',term,true,'{"mode":"carrier","email":"test@example.invalid"}');
 perform pg_temp.ic_test('voucher collection succeeds',r->>'ok'='true');
 perform pg_temp.ic_test('voucher exactly once',(select sessions_remaining=1 from member_tickets where id='CC-IC-V') and (select count(*)=1 and sum(delta)=1 from ticket_logs where ticket_id='CC-IC-V'));
 perform pg_temp.ic_test('voucher and real amount retained',(select deal_amount=3700 and list_price=4000 from purchases where id='PUR-INST-receipt_voucher'));
 r:=fn_installment_collect_v2('CC-IC-VT','receipt_voucher',term,true,'{"mode":"carrier","email":"test@example.invalid"}');
 perform pg_temp.ic_test('voucher retry no second deduction',r->>'already'='true' and (select sessions_remaining=1 from member_tickets where id='CC-IC-V'));
 term:=fn_installment_terms('CC-IC-VT',4,3400,'cash',2);
 r:=fn_installment_collect_v2('CC-IC-VT','receipt_overcap',term,true,'{"mode":"none"}');
 perform pg_temp.ic_test('voucher cap enforced server side',r->>'error_code'='VOUCHER.LIMIT');
 term:=fn_installment_terms('CC-IC-VT',4,4000,'cash',0);
 r:=fn_installment_collect_v2('CC-IC-VT','receipt_noemail',term,true,'{"mode":"carrier"}');
 perform pg_temp.ic_test('invoice delivery fields required',r->>'error_code'='INVOICE.DELIVERY_REQUIRED');
 r:=fn_installment_collect_v2('CC-IC-VT','receipt_ubn',term,true,'{"mode":"ubn","ubn":"12345678","email":"test@example.invalid"}');
 perform pg_temp.ic_test('company invoice choice supported',r->>'ok'='true');
 select * into c from contracts where id='CC-IC-C';
 blocked:=false;begin update contracts set installment_signs='[]' where id=c.id;exception when others then blocked:=sqlerrm='INSTALLMENT.SIGNED_IMMUTABLE';end;
 perform pg_temp.ic_test('signed evidence cannot be deleted',blocked);
 blocked:=false;begin update contracts set installment_signs=jsonb_set(installment_signs,'{0,amount}','1') where id=c.id;exception when others then blocked:=sqlerrm='INSTALLMENT.SIGNED_IMMUTABLE';end;
 perform pg_temp.ic_test('signed evidence cannot be edited',blocked);
 blocked:=false;begin term:=fn_installment_terms('CC-IC-VT',1,0,'cash',0);exception when others then blocked:=sqlerrm='INSTALLMENT.INVALID_INPUT';end;
 perform pg_temp.ic_test('fully unlocked cannot collect again',blocked);
end$$;
select jsonb_build_object('passed',count(*) filter(where ok),'failed',count(*) filter(where not ok),'failures',coalesce(jsonb_agg(name) filter(where not ok),'[]')) as result from ic_results;
insert into member_tickets(id,member_id,ticket_type_id,plan_name,sessions_total,sessions_remaining,unlocked_sessions,amount_paid,status,installment)
values('CC-IC-Z','CC-IC-M','CC-IC-TT','zero payment',12,12,4,4000,'usable','{"count":3,"current":1,"segments":[4,4,4],"amounts":[4000,4000,4000],"paid":[true,false,false]}');
do $$declare term jsonb;r jsonb;rid text;blocked boolean;
begin
 perform set_config('request.jwt.claim.sub','7d01aa40-db57-4e26-a49a-b3a5d1dc5722',true);
 term:=fn_installment_terms('CC-IC-Z',2,0,'cash',0);
 r:=fn_installment_request_v2('CC-IC-Z',term);
 perform pg_temp.ic_test('missing contract fails closed',r->>'error_code'='CONTRACT.NOT_UNIQUE');
 insert into contracts(id,member_id,ticket_id,sign_type,signed_at) values('CC-IC-ZC','CC-IC-M','CC-IC-Z','remote',now());
 update contracts set installment_signs=jsonb_build_array(jsonb_build_object('n',2,'terms',term,'signature','old legacy image','signed_at',now())) where id='CC-IC-ZC';
 r:=fn_installment_collect_v2('CC-IC-Z','receipt_legacy',term,false,'{"mode":"none"}');
 perform pg_temp.ic_test('legacy signature without immutable request cannot open new terms',r->>'error_code'='INSTALLMENT.SIGNATURE_REQUIRED');
 r:=fn_installment_request_v2('CC-IC-Z',term);rid:=r->>'request_id';
 r:=fn_installment_request_v2('CC-IC-Z',term);
 perform pg_temp.ic_test('same unsigned request idempotent',r->>'request_id'=rid and (select jsonb_array_length(installment_signs)=2 from contracts where id='CC-IC-ZC'));
 blocked:=false;begin update contracts set installment_signs=jsonb_set(installment_signs,'{1,signature}',to_jsonb('forged signature'::text)) where id='CC-IC-ZC';exception when others then blocked:=sqlerrm='INSTALLMENT.MEMBER_SIGNATURE_REQUIRED';end;
 perform pg_temp.ic_test('desk cannot fabricate member signature',blocked);
 perform set_config('request.jwt.claim.sub','07111900-0000-4000-8000-000000000001',true);
 r:=fn_member_sign_installment_v2('CC-IC-ZC',rid,'data:image/png;base64,'||repeat('Z',240));
 perform pg_temp.ic_test('zero fee terms can be signed',r->>'ok'='true');
 perform set_config('request.jwt.claim.sub','7d01aa40-db57-4e26-a49a-b3a5d1dc5722',true);
 r:=fn_installment_collect_v2('CC-IC-Z','receipt_zero',term,false,'{"mode":"none"}');
 perform pg_temp.ic_test('explicit zero payment allowed',r->>'ok'='true');
 perform pg_temp.ic_test('partial stage preserves progress',(select unlocked_sessions=6 and amount_paid=4000 and installment->>'current'='1' from member_tickets where id='CC-IC-Z'));
 term:=fn_installment_terms('CC-IC-Z',2,2000,'cash',0);
 perform pg_temp.ic_test('remaining partial stage still labeled period2',term->>'period_from'='2' and term->>'period_to'='2');
 insert into contracts(id,member_id,ticket_id,sign_type,signed_at) values('CC-IC-ZD','CC-IC-M','CC-IC-Z','paper',now());
 r:=fn_installment_collect_v2('CC-IC-Z','receipt_duplicate',term,true,'{"mode":"none"}');
 perform pg_temp.ic_test('duplicate contract fails closed',r->>'error_code'='CONTRACT.NOT_UNIQUE');
end$$;
select jsonb_build_object('passed',count(*) filter(where ok),'failed',count(*) filter(where not ok),'failures',coalesce(jsonb_agg(name) filter(where not ok),'[]'),'pins',(select jsonb_object_agg(p.oid::regprocedure::text,md5(p.prosrc)) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('fn_installment_terms','fn_installment_request_v2','fn_member_sign_installment_v2','fn_member_sign_installment','fn_installment_collect_v2','fn_installment_collection_guard','fn_installment_signature_guard'))) as result from ic_results;
